# owner: platform
"""Lay students out in seating rows."""

from rosterkit.errors import ProjectError


def _chunks(items, size):
    return [
        items[i:i + size]
        for i in range(0, len(items), size)
    ]


def _row_line(number, row):
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"


# ---
def seat_rows(students, seats_per_row):
    if seats_per_row < 1 or not students:
        raise ProjectError("need students and seats")
    key = lambda s: (s.last_name, s.first_name)
    rows = _chunks(sorted(students, key=key), seats_per_row)
    return [_row_line(n, r) for n, r in enumerate(rows, 1)]

